def compute(vars):
    notes_payable = vars["v1"]
    sojitz_payable = vars["v2"]
    total_outstanding = notes_payable + sojitz_payable
    if total_outstanding == 0:
        return None
    percentage = notes_payable / total_outstanding * 100
    return {
        "value": percentage,
        "trace": {
            "notes_payable": notes_payable,
            "sojitz_payable": sojitz_payable,
            "total_outstanding": total_outstanding,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
